import React from "react";
import {
  BrowserRouter as Router,
  Route,
  Routes,
} from "react-router-dom";
import { Security } from "@okta/okta-react";
import { oktaAuth } from "./config/OktaAuth";

import Header from "./components/Header";
import Menu from "./components/Menu";
import AdminDashboard from "./pages/AdminDashboard";
import ClientDashboard from "./pages/ClientDashboard";
import StaffDashboard from "./pages/StaffDashboard";
import HomePage from "./pages/HomePage";
import PostLogin from "./pages/PostLogin";
import CustomSecureRoute from "./pages/CustomSecureRoute";
import CertDB from "./pages/CertDB";
import UserTable from "./components/UserTable";

import { useUserRoles } from "./hooks/useUserRoles";

import "./App.css";

// ✅ This component is inside <Security>, so it can safely use hooks
const ProtectedRoutes = () => {
  const roles = useUserRoles();

  return (
    <>
      <Header />
      <div className="container-fluid page-body-wrapper">
        <Menu />
        <div className="main-panel">
          <div className="content-wrapper">
            <div className="content">
              <Routes>
                <Route path="/" element={<HomePage />} />
                <Route path="/login/callback" element={<PostLogin />} />

                <Route
                  path="/home/admin"
                  element={
                    <CustomSecureRoute>
                      <AdminDashboard />
                    </CustomSecureRoute>
                  }
                />
                <Route
                  path="/home/staff"
                  element={
                    <CustomSecureRoute>
                      <StaffDashboard />
                    </CustomSecureRoute>
                  }
                />
                <Route
                  path="/home/client"
                  element={
                    <CustomSecureRoute>
                      <ClientDashboard />
                    </CustomSecureRoute>
                  }
                />
                <Route
                  path="/cert-db"
                  element={
                    <CustomSecureRoute>
                      <CertDB />
                    </CustomSecureRoute>
                  }
                />

                {/* ✅ Admin-only route */}
                {roles.includes("admin") && (
                  <Route
                    path="/user"
                    element={
                      <CustomSecureRoute>
                        <UserTable />
                      </CustomSecureRoute>
                    }
                  />
                )}
              </Routes>
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

function App() {
  return (
    <Router>
      <Security
        oktaAuth={oktaAuth}
        restoreOriginalUri={(oktaAuth, originalUri) =>
          window.location.replace(originalUri || "/")
        }
      >
        <ProtectedRoutes />
      </Security>
    </Router>
  );
}

export default App;
